from decision_diff.core import normalize as core_normalize
from decision_diff.configs import REAL

def normalize(document, app_id, source, params):
    return core_normalize(document, app_id, source, REAL)

from decision_diff.core import compare as core_compare

def compare(before_rows, after_rows, params):
    return core_compare(before_rows, after_rows)

from decision_diff.segments import build_segment as core_segment

def build_segment(before_doc, after_doc, app_id, params):
    return core_segment(before_doc, after_doc, app_id)

from decision_diff.reporting import pivot_facts, summarize

def aggregate(comparison_rows, segments, params):
    return {'pivot_facts': pivot_facts(comparison_rows), 'summary': summarize(comparison_rows, segments)}

