def run(mart, params=None):
    total = mart.total_apps()
    changed = mart.app_ids(diff_flag=1)
    share = len(changed) / total if total else 0.0
    return [{'LABEL': CHECK['label'], 'SOURCE': 'AFTER', 'ARGUMENT': 'all', 'CNT': len(changed),
             'TOTAL': total, 'METRIC': round(share, 4), 'APP_IDS': changed[:20],
             'RESULT': 'FAIL' if share > params['max_share'] else 'PASS',
             'CONFIDENCE': 'HIGH' if total >= 30 else 'LOW'}]

CHECK = {'id': 'changed_share', 'label': 'Share of changed apps', 'params': {'max_share': 0.5}, 'entrypoint': run}
